public class Solution {
    public static class Account {
        private String owner;
        private int balance;

        public Account(String name, int start) {
            owner = name;
            balance = start;
        }

        public String getOwner() {
            return owner;
        }

        public int getBalance() {
            return balance;
        }
    }
}

